"""Batch intake surface; shares Studio tokens and operator authentication."""
from tubeforge.api.studio_shell import STUDIO_CSS

BATCH_HTML = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Batch plans — TubeForge</title><style>''' + STUDIO_CSS + '''
main{max-width:1080px;margin:32px auto;padding:0 20px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}th{font-weight:500;color:var(--muted)}.table-frame{overflow:auto}textarea{display:block;width:100%;min-height:200px}button{margin:12px 8px 12px 0} @media(max-width:640px){th,td{padding:8px;font-size:12px}}</style>
<main><a href="/">TubeForge Studio</a><h1>Batch plans</h1><p>Import shorts for review. Publish dates are metadata only.</p>
<form id="batchForm"><label for="batchFile">Markdown file</label><input id="batchFile" type="file" accept=".md,.markdown,text/markdown,text/plain"><label for="batchText">Markdown plan</label><textarea id="batchText" required></textarea><button id="validate" type="submit">Validate and preview</button><button id="commit" type="button" disabled>Commit import</button></form>
<p id="result" role="status" aria-live="polite"></p><div class="table-frame"><table><thead><tr><th>Short</th><th>Publish metadata</th><th>Channel</th><th>Length</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table></div></main>
<script>
const form=document.querySelector('#batchForm'),input=document.querySelector('#batchText'),file=document.querySelector('#batchFile'),commit=document.querySelector('#commit'),result=document.querySelector('#result'),rows=document.querySelector('#rows');
let validated=null,busy=false;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function display(items){rows.innerHTML=items.map(x=>{const s=x.short;return `<tr><td>${esc(s.title)}<br>${esc(s.id)}</td><td>${esc(s.publish_at||'Unassigned')}</td><td>${esc(s.channel||'Unassigned')}</td><td>${s.length_s}s</td><td>${esc(x.action||x.status)}</td></tr>`}).join('')||'<tr><td colspan="5">No imported shorts yet.</td></tr>';}
input.oninput=()=>{validated=null;commit.disabled=true};file.onchange=async()=>{input.value=file.files[0]?await file.files[0].text():'';input.oninput()};
async function submit(save){if(busy)return;if(save&&validated!==input.value)return;busy=true;commit.disabled=true;document.querySelector('#validate').disabled=true;result.textContent=save?'Saving import…':'Validating…';try{const csrf=decodeURIComponent((document.cookie.match(/(?:^|; )tubeforge_csrf=([^;]+)/)||[])[1]||'');const response=await fetch('/api/batch-plans/import',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({markdown:input.value,commit:save})});const data=await response.json();if(!response.ok){validated=null;throw Error(Array.isArray(data.detail)?data.detail.map(e=>`Line ${e.line||'?'}: ${e.message||e.msg}`).join(' / '):data.detail)}display(data.items);validated=input.value;result.textContent=save?'Import saved. Conflicts were preserved.':'Validation passed. Review the rows before committing.';}catch(e){result.textContent=e.message;}finally{busy=false;document.querySelector('#validate').disabled=false;commit.disabled=validated!==input.value||validated===null;}}
form.onsubmit=e=>{e.preventDefault();submit(false)};commit.onclick=()=>submit(true);fetch('/api/batch-plans').then(async r=>{if(!r.ok)throw Error('Could not load imported shorts');display(await r.json())}).catch(e=>result.textContent=e.message);
</script></html>'''
